from pathlib import Path
p=Path('apps/mindmark-web/src/views/teacher/GradingView.vue')
text=p.read_text(encoding='utf-8-sig')
text=text.replace("import { computed, onMounted, ref, watch } from 'vue';", "import { computed, onMounted, reactive, ref } from 'vue';")
text=text.replace("import { useClientPagination } from '@/composables/useClientPagination';\n", "")
text=text.replace("import { listGradingTasks, reviewGradingTask } from '@/services/gradingService';", "import {\n  listGradingTaskAllItems,\n  listGradingTaskItemsPage,\n  listGradingTasksPage,\n  reviewGradingTask,\n} from '@/services/gradingService';")
old='''const operationMessage = ref('');\nconst {\n  pagination: taskPagination,\n  items: pagedTasks,\n  clampPage: clampTaskPage,\n  handleChange: handleTaskPaginationChange,\n} = useClientPagination(() => tasks.value, 8);\n\nconst selectedTask = computed(\n  () => tasks.value.find((task) => task.id === selectedTaskId.value) ?? tasks.value[0] ?? null,\n);\nconst selectedQuestionGrades = computed<QuestionGrade[]>(() =>\n  selectedTask.value?.questionGrades ?? [],\n);\nconst {\n  pagination: questionPagination,\n  items: pagedQuestionGrades,\n  resetPage: resetQuestionPage,\n  clampPage: clampQuestionPage,\n  handleChange: handleQuestionPaginationChange,\n} = useClientPagination(() => selectedQuestionGrades.value, 10);\n'''
new='''const operationMessage = ref('');\nconst tasksTotal = ref(0);\nconst questionTotal = ref(0);\nconst questionGrades = ref<QuestionGrade[]>([]);\nconst scoreOverrides = ref<Record<string, number>>({});\nconst taskPagination = reactive({ page: 1, pageSize: 8 });\nconst questionPagination = reactive({ page: 1, pageSize: 10 });\nconst pagedTasks = computed(() => tasks.value);\nconst pagedQuestionGrades = computed(() => questionGrades.value);\nconst selectedQuestionGrades = computed(() => questionGrades.value);\n\nconst selectedTask = computed(\n  () => tasks.value.find((task) => task.id === selectedTaskId.value) ?? tasks.value[0] ?? null,\n);\n'''
if old not in text:
    raise SystemExit('pagination block not found')
text=text.replace(old,new)
text=text.replace('''const scoreValue = (task: GradingTask, questionId: string) => {\n  const grade = task.questionGrades.find((item) => item.questionId === questionId);\n\n  return grade?.finalScore ?? grade?.aiSuggestedScore ?? grade?.autoScore ?? 0;\n};\n''', '''const scoreValue = (task: GradingTask, questionId: string) => {\n  const override = scoreOverrides.value[questionId];\n  if (override !== undefined) {\n    return override;\n  }\n\n  const grade = questionGrades.value.find((item) => item.questionId === questionId)\n    ?? task.questionGrades.find((item) => item.questionId === questionId);\n\n  return grade?.finalScore ?? grade?.aiSuggestedScore ?? grade?.autoScore ?? 0;\n};\n\nconst gradeScoreValue = (grade: QuestionGrade) =>\n  scoreOverrides.value[grade.questionId]\n    ?? grade.finalScore\n    ?? grade.aiSuggestedScore\n    ?? grade.autoScore\n    ?? 0;\n''')
text=text.replace('''  const inputScore = Number(target.value);\n  tasks.value = tasks.value.map((item) => {\n    if (item.id !== task.id) {\n      return item;\n    }\n\n    return {\n      ...item,\n      questionGrades: item.questionGrades.map((grade) =>\n        grade.questionId === questionId\n          ? { ...grade, finalScore: Math.max(0, Math.min(grade.maxScore, inputScore)) }\n          : grade,\n      ),\n    };\n  });\n};\n''', '''  const inputScore = Number(target.value);\n  const grade = questionGrades.value.find((item) => item.questionId === questionId);\n  const safeScore = Math.max(0, Math.min(grade?.maxScore ?? Number.MAX_SAFE_INTEGER, inputScore));\n  scoreOverrides.value = { ...scoreOverrides.value, [questionId]: safeScore };\n  questionGrades.value = questionGrades.value.map((item) =>\n    item.questionId === questionId ? { ...item, finalScore: safeScore } : item,\n  );\n};\n\nconst loadQuestionGrades = async () => {\n  const task = selectedTask.value;\n  if (!task) {\n    questionGrades.value = [];\n    questionTotal.value = 0;\n    return;\n  }\n\n  const response = await listGradingTaskItemsPage(task, {\n    page: questionPagination.page,\n    pageSize: questionPagination.pageSize,\n  });\n  questionGrades.value = response.items.map((grade) => ({\n    ...grade,\n    ...(scoreOverrides.value[grade.questionId] !== undefined\n      ? { finalScore: scoreOverrides.value[grade.questionId] }\n      : {}),\n  }));\n  questionTotal.value = response.total;\n  questionPagination.page = response.page;\n  questionPagination.pageSize = response.pageSize;\n};\n''')
text=text.replace('''    tasks.value = await listGradingTasks();\n    selectedTaskId.value = selectedTaskId.value || tasks.value[0]?.id || '';\n    clampTaskPage();\n    clampQuestionPage();\n''', '''    const response = await listGradingTasksPage({\n      page: taskPagination.page,\n      pageSize: taskPagination.pageSize,\n    });\n    tasks.value = response.items;\n    tasksTotal.value = response.total;\n    taskPagination.page = response.page;\n    taskPagination.pageSize = response.pageSize;\n    selectedTaskId.value = tasks.value.some((task) => task.id === selectedTaskId.value)\n      ? selectedTaskId.value\n      : tasks.value[0]?.id || '';\n    await loadQuestionGrades();\n''')
text=text.replace('''    tasks.value = [];\n    selectedTaskId.value = '';\n''', '''    tasks.value = [];\n    questionGrades.value = [];\n    tasksTotal.value = 0;\n    questionTotal.value = 0;\n    selectedTaskId.value = '';\n''')
text=text.replace('''      tasks.value = tasks.value.map((item) => (item.id === updated.id ? updated : item));\n      clampQuestionPage();\n      operationMessage.value = `${updated.studentName} 的答卷已完成复核，可进入成绩发布前检查。`;\n''', '''      tasks.value = tasks.value.map((item) => (item.id === updated.id ? { ...updated, questionGrades: [] } : item));\n      scoreOverrides.value = {};\n      await loadQuestionGrades();\n      operationMessage.value = `${updated.studentName} 的答卷已完成复核，可进入成绩发布前检查。`;\n''')
# overrides in submit
text=text.replace('''  const overrides: GradingScoreOverride[] = task.questionGrades.map((grade) => ({\n    questionId: grade.questionId,\n    finalScore: scoreValue(task, grade.questionId),\n    ...(grade.teacherComment ? { teacherComment: grade.teacherComment } : {}),\n  }));\n''', '''  const allQuestionGrades = await listGradingTaskAllItems(task);\n  const overrides: GradingScoreOverride[] = allQuestionGrades.map((grade) => ({\n    questionId: grade.questionId,\n    finalScore: gradeScoreValue(grade),\n    ...(grade.teacherComment ? { teacherComment: grade.teacherComment } : {}),\n  }));\n''')
old_watch='''watch(selectedTaskId, () => {\n  resetQuestionPage();\n});\n\nonMounted(() => {'''
new_funcs='''const selectTask = async (taskId: string) => {\n  if (selectedTaskId.value === taskId) {\n    return;\n  }\n\n  selectedTaskId.value = taskId;\n  questionPagination.page = 1;\n  scoreOverrides.value = {};\n  await loadQuestionGrades();\n};\n\nconst handleTaskPaginationChange = async (page: number, pageSize: number) => {\n  taskPagination.page = page;\n  taskPagination.pageSize = pageSize;\n  questionPagination.page = 1;\n  scoreOverrides.value = {};\n  await loadTasks();\n};\n\nconst handleQuestionPaginationChange = async (page: number, pageSize: number) => {\n  questionPagination.page = page;\n  questionPagination.pageSize = pageSize;\n  await loadQuestionGrades();\n};\n\nonMounted(() => {'''
if old_watch not in text:
    raise SystemExit('watch block not found')
text=text.replace(old_watch,new_funcs)
text=text.replace('@click="selectedTaskId = task.id"', '@click="selectTask(task.id)"')
text=text.replace(':total="tasks.length"', ':total="tasksTotal"')
text=text.replace('v-if="tasks.length > taskPagination.pageSize"', 'v-if="tasksTotal > taskPagination.pageSize"')
text=text.replace('v-if="selectedQuestionGrades.length > questionPagination.pageSize"', 'v-if="questionTotal > questionPagination.pageSize"')
text=text.replace(':total="selectedQuestionGrades.length"', ':total="questionTotal"')
p.write_text(text,encoding='utf-8')
